<script setup lang="ts">
/**
 * MediaGrid (R2.2) — virtualized poster grid for the Browse surface.
 *
 * Ports the locked R0 art direction (`src/dev/mockups/browse-grid.html`): an
 * auto-fit poster grid whose column count is driven by the user's `cardSize`
 * preference, with a 2:3 rhythm and the Nocturne gaps.
 *
 * Virtualization: only the rows intersecting the viewport (plus an overscan
 * band) are ever in the DOM, so a library of thousands of items stays at 60fps.
 * The windowing arithmetic lives in `./virtual-grid.ts` (pure, unit-tested);
 * this component only measures (guarded — jsdom has no layout) and renders the
 * selected slice, offsetting it with a `translateY` spacer inside a full-height
 * sizer so the native scrollbar stays accurate.
 *
 * When measurement is unavailable (SSR / jsdom / zero-width container) it
 * degrades gracefully to rendering every item — virtualization is a pure
 * progressive enhancement.
 *
 * Infinite scroll: an `IntersectionObserver` sentinel near the end emits
 * `load-more`; a "back to top" affordance appears once scrolled well past the
 * fold. Skeleton rows on the initial load match the final layout (no shift).
 */
import { computed, onBeforeUnmount, onMounted, ref, watch, nextTick } from 'vue';
import type { MediaItem } from '../types/media-item';
import MediaCard from './MediaCard.vue';
import Icon from './Icon.vue';
import { usePreferencesStore } from '../stores/usePreferencesStore';
import {
  COL_GAP,
  REM_BASIS_PX,
  computeCardWidth,
  computeColumns,
  computeRowHeight,
  computeWindow,
  effectiveItemCount,
  fixedRowContentHeight,
  labelHeightForRootFontSize,
  shouldLoadMore,
} from './virtual-grid';

const props = withDefaults(
  defineProps<{
    /** Items to render (the already-loaded page set). */
    items: MediaItem[];
    /** Full server result count. When set, the grid is sized to this up front so
     *  the page length is final immediately and not-yet-loaded rows render as
     *  skeletons until scrolled into view (on-demand paging fills them in). */
    total?: number | null;
    /** Initial load — show skeleton rows instead of cards. */
    loading?: boolean;
    /** Appending a further page (controls the bottom loading row). */
    loadingMore?: boolean;
    /** More items remain — enables the infinite-scroll sentinel. */
    hasMore?: boolean;
    /** Min card width (px). Overrides the `cardSize` preference when set. */
    cardSize?: number;
    /**
     * Force the column count, overriding the `cardSize`-derived auto-fit count.
     *
     * This is the ONLY correct way for a `#card`-slot renderer to change the
     * column count (S68's list view pins it to 1): the same value feeds BOTH the
     * inline `grid-template-columns` and the windowing arithmetic, so layout and
     * virtualization stay on the same numbers. A CSS `grid-template-columns`
     * override would need `!important` to beat that inline style and would then
     * desync the two — blank bands, mis-positioned rows and wrong `need-range`
     * pages. Values < 1 (or non-finite) are ignored.
     */
    columns?: number;
    /**
     * Force the row height in px, INCLUDING the row gap beneath it — build it
     * with `computeFixedRowHeight()`.
     *
     * Required by any `#card`-slot renderer whose rows are not 2:3 posters:
     * `computeRowHeight()` scales `POSTER_RATIO` with the card width, which for a
     * single full-width list row computes a row several times too tall.
     *
     * Setting this also makes the GRID ENFORCE the contract rather than trusting
     * each renderer to honour it: the row tracks get `grid-auto-rows` at exactly
     * `rowHeight - ROW_GAP`, and the not-yet-loaded placeholder cells get the same
     * height. So a renderer (or a later MediaCard restyle) whose content outgrows
     * the row is clipped by its own `overflow`, never allowed to push the next row
     * out of the position `padTop` reserved for it.
     */
    rowHeight?: number;
    /** Skeleton cards shown during the initial load. */
    skeletonCount?: number;
    /** Extra rows rendered above/below the visible band. */
    overscan?: number;
    /** Admin opt-in (U5): render each card's "Match" action + forward `match`. */
    canMatch?: boolean;
  }>(),
  { loading: false, loadingMore: false, hasMore: false, skeletonCount: 18, overscan: 2, canMatch: false },
);

const emit = defineEmits<{
  (e: 'load-more'): void;
  /** The absolute index window now in view (incl. overscan). The host loads any
   *  pages covering it — this is what fills the pre-sized grid after an A-Z jump,
   *  where `load-more` (append-at-end) can't reach the jumped-to offset. */
  (e: 'need-range', startIndex: number, endIndex: number): void;
  (e: 'play', item: MediaItem): void;
  (e: 'watchlist', item: MediaItem): void;
  (e: 'info', item: MediaItem): void;
  (e: 'match', item: MediaItem): void;
  (e: 'mark-watched', item: MediaItem): void;
  (e: 'refresh', item: MediaItem): void;
  (e: 'choose-poster', item: MediaItem): void;
  (e: 'remove', item: MediaItem): void;
  /** Admin ⋯-menu "Edit metadata" — host opens the metadata-match modal. */
  (e: 'edit-metadata', item: MediaItem): void;
  /** Admin ⋯-menu "Explore item data" — host opens the read-only inspector. */
  (e: 'explore-data', item: MediaItem): void;
}>();

defineSlots<{
  /** Override the per-item card. Receives the item + its absolute index. */
  card?: (props: { item: MediaItem; index: number }) => unknown;
  /** Replace the empty state. */
  empty?: () => unknown;
}>();

const prefs = usePreferencesStore();
const cardSize = computed(() => props.cardSize ?? prefs.cardSize ?? 200);

const sizerEl = ref<HTMLElement | null>(null);
const sentinelEl = ref<HTMLElement | null>(null);

// --- measurement (all guarded; stays at defaults under jsdom/SSR) ---
const containerWidth = ref(0);
const viewportHeight = ref(0);
const scrollTop = ref(0); // grid-top scrolled above viewport top (≥ 0)
/**
 * The viewer's actual root font size (px) — the second input the poster grid's row
 * height depends on (S69 review r2, finding 2a). `.media-card__caption` is entirely
 * rem-valued, so at a 20px root it is ~64px tall against an assumed 56 and every row
 * under-reserves; `labelHeightForRootFontSize()` corrects for that. Read in
 * `measure()` (mount + ResizeObserver only, never per scroll tick) and defaulted to
 * the 16px basis so jsdom/SSR keep the documented arithmetic exactly.
 *
 * ⚠ HOW LIVE THIS ACTUALLY IS (S69 review r3, LOW-2): it is refreshed only when
 * `measure()` runs, i.e. on mount, on `window.resize`, and when the OBSERVED BOX
 * (`.media-grid-sizer`) changes size. A root font-size change is not itself a resize
 * of that box — inside the app shell it happens to become one, because
 * `.shell__main`'s padding is rem-valued (`AppLayout.vue`, `padding: var(--space-6)
 * var(--space-5)`), so the grid's content width moves ~10px per 4px of root and the
 * ResizeObserver delivers (measured in Chrome: 1 delivery for a 16→20px root change,
 * versus 0 with the same tree px-padded). `MediaGrid` is a PUBLIC export, though, so a
 * consumer that mounts it in a root-font-size-independent container AND offers a
 * font-size control keeps the previous `labelHeight` until the next genuine resize.
 * Not a regression — the pre-fix constant was wrong at every non-16px root,
 * permanently — and a fresh load always reads the right value on mount. The durable
 * fix is the same one the gap half already names: measure the caption (and the gap)
 * once at mount and feed the measurement in, rather than deriving both from the root.
 */
const rootFontSize = ref(REM_BASIS_PX);

/**
 * Cached offset of the sizer element's top edge from the document top (px).
 * Invalidated by the ResizeObserver (layout changes) and recomputed in measure().
 * Using this instead of getBoundingClientRect() per scroll tick eliminates a
 * forced layout read on every scroll event — critical on low-end devices.
 */
let sizerTop = 0;

// Throttle scroll measurements to avoid measuring on every scroll tick
// (scroll can fire hundreds of times per second). We use a timestamp check
// rather than rAF because Firefox aggressively throttles rAF during
// scrolling, causing the window position to "freeze" visually.
let lastScrollMeasureTime = 0;
const SCROLL_MEASURE_THROTTLE_MS = 16;

function measure(): void {
  const el = sizerEl.value;
  const vh = typeof window !== 'undefined' ? window.innerHeight : 0;
  if (vh > 0) viewportHeight.value = vh;
  // getBoundingClientRect is only called here (on mount and ResizeObserver),
  // NOT on every scroll tick — scrollTop is derived from window.scrollY instead.
  if (el && typeof el.getBoundingClientRect === 'function') {
    const rect = el.getBoundingClientRect();
    if (rect.width > 0) containerWidth.value = rect.width;
    sizerTop = typeof window !== 'undefined' ? window.scrollY + rect.top : 0;
  }
  // One computed-style read per measure (mount + layout change), not per scroll
  // tick. jsdom reports `"medium"` → NaN → the 16px basis is kept. Note this is as
  // live as the OBSERVED BOX, not as live as the root font size itself — see the
  // `rootFontSize` docblock for the one downstream shape where that differs.
  if (
    typeof window !== 'undefined' &&
    typeof document !== 'undefined' &&
    typeof window.getComputedStyle === 'function'
  ) {
    const px = Number.parseFloat(window.getComputedStyle(document.documentElement).fontSize);
    if (Number.isFinite(px) && px > 0) rootFontSize.value = px;
  }
}

/**
 * Scroll handler: reads window.scrollY directly (no getBoundingClientRect).
 * sizerTop is cached and updated only by measure() (ResizeObserver fires on
 * layout changes, keeping the cache valid for the scroll-driven case).
 * measure() is NOT called here — containerWidth/viewportHeight are stable
 * after layout and are updated by the ResizeObserver on any size change.
 */
function throttledMeasure(): void {
  const now = performance.now();
  if (now - lastScrollMeasureTime >= SCROLL_MEASURE_THROTTLE_MS) {
    lastScrollMeasureTime = now;
    // scrollTop derived from cached sizerTop — no layout read needed.
    scrollTop.value = typeof window !== 'undefined' ? Math.max(0, window.scrollY - sizerTop) : 0;
  }
}

// rAF-coalesced scroll/resize so we measure at most once per frame.
let frame = 0;
function scheduleMeasure(): void {
  if (frame) return;
  const raf =
    typeof requestAnimationFrame === 'function' ? requestAnimationFrame : (cb: FrameRequestCallback) => setTimeout(() => cb(0), 16) as unknown as number;
  frame = raf(() => {
    frame = 0;
    measure();
  });
}

// --- derived layout ---
/**
 * Guards visibleItems recompute: only re-slice when the window band or the source
 * `items` array actually change. Uses a plain closure variable (not reactive) to
 * avoid vue/no-side-effects in computed. Each component instance gets its own
 * closure, so no cross-instance pollution.
 *
 * `source` is part of the cache key (S35): on-demand paging fills skeleton slots
 * by REPLACING `items` with a new array (see useMediaStore.placePage), WITHOUT
 * moving the scroll window. Keying only on start/end would then keep returning
 * the previously-cached slice — still holding `null` for the just-loaded indices,
 * so those posters stayed stuck as skeletons until a scroll shifted the band and
 * incidentally busted the cache. Keying on the array identity too makes a fill
 * re-slice immediately, while a pure scroll tick (same array, same band) still
 * skips the work.
 */
type WindowCache = {
  startIndex: number;
  endIndex: number;
  source: readonly MediaItem[];
  items: { item: MediaItem | null; index: number }[];
};
let windowCache: WindowCache | null = null;

/** A caller-forced count wins over the measured auto-fit one (see the prop). */
const forcedColumns = computed(() => {
  const n = props.columns;
  return typeof n === 'number' && Number.isFinite(n) && n >= 1 ? Math.trunc(n) : null;
});
/** A caller-forced row height wins over the poster-derived one (see the prop). */
const forcedRowHeight = computed(() => {
  const h = props.rowHeight;
  return typeof h === 'number' && Number.isFinite(h) && h > 0 ? h : null;
});
/** True while the rows are a caller-pinned fixed height (non-poster renderer). */
const fixedRows = computed(() => forcedRowHeight.value !== null);

// Named `effective*` (like `effectiveCount` below) rather than `columns`/`rowHeight`
// so they never shadow the same-named props above.
const effectiveColumns = computed(
  () => forcedColumns.value ?? computeColumns(containerWidth.value, cardSize.value, COL_GAP),
);
const effectiveRowHeight = computed(
  () =>
    forcedRowHeight.value ??
    computeRowHeight(
      computeCardWidth(containerWidth.value, effectiveColumns.value, COL_GAP),
      // The caption block is rem-valued, so its height follows the root font size
      // even though the gap above it no longer does (S69 review r2, finding 2a).
      labelHeightForRootFontSize(rootFontSize.value),
    ),
);

/** Virtualize only once we have real measurements; otherwise render everything. */
const virtualized = computed(() => containerWidth.value > 0 && effectiveRowHeight.value > 0);

/** Sizing count: the server `total` when known (so the page is its final length
 *  up front), else the loaded count. */
const effectiveCount = computed(() => effectiveItemCount(props.items.length, props.total));

const windowResult = computed(() =>
  computeWindow({
    scrollTop: scrollTop.value,
    viewportHeight: viewportHeight.value,
    rowHeight: effectiveRowHeight.value,
    columns: effectiveColumns.value,
    itemCount: effectiveCount.value,
    overscan: props.overscan,
  }),
);

const visibleItems = computed(() => {
  if (!virtualized.value) {
    return props.items.map((item, index) => ({ item: item as MediaItem | null, index }));
  }
  // Read `items` up-front so the computed ALWAYS tracks it as a reactive
  // dependency — even on a cache hit. Without this read the cache-hit early
  // return never touches `props.items`, so a later on-demand fill (a new array)
  // would not invalidate the computed and the freshly-loaded posters would stay
  // skeletons until a scroll happened to change the window band (S35).
  const source = props.items;
  const { startIndex, endIndex } = windowResult.value;
  // Gating: skip recompute when neither the window band NOR the source array
  // moved. The scrollTop ref updates on every tick, but startIndex/endIndex only
  // change when the row band actually shifts, and `source` only changes when a
  // page is (re)placed — so a pure scroll tick still avoids re-slicing.
  if (
    windowCache &&
    windowCache.startIndex === startIndex &&
    windowCache.endIndex === endIndex &&
    windowCache.source === source
  ) {
    return windowCache.items;
  }
  const out: { item: MediaItem | null; index: number }[] = [];
  // Indices past the loaded set render as skeletons (pre-sized grid); they fill
  // in once on-demand paging fetches them.
  for (let i = startIndex; i < endIndex; i++) out.push({ item: source[i] ?? null, index: i });
  windowCache = { startIndex, endIndex, source, items: out };
  return out;
});

// On-demand paging for the pre-sized grid: when the rendered window reaches the
// loaded edge, ask the host for the next page. The bottom sentinel can't drive
// this once the sizer is the full `total` height (it only fires at the very end).
watch(
  () =>
    [windowResult.value.endIndex, props.items.length, props.hasMore, props.loading, props.loadingMore] as const,
  ([endIndex, loaded, hasMore, loading, loadingMore]) => {
    if (virtualized.value && shouldLoadMore(endIndex, loaded, { hasMore, loading, loadingMore })) {
      emit('load-more');
    }
  },
);

// Random-access paging: emit the visible window so the host can load whatever
// pages it covers — works for both scrolling AND the A-Z jump (load-more only
// appends at the end and can't fill a jumped-to offset). Debounced so a fast
// scroll/jump fetches the SETTLED window, not every page flown past.
let needRangeTimer: ReturnType<typeof setTimeout> | undefined;
watch(
  () => [virtualized.value, windowResult.value.startIndex, windowResult.value.endIndex] as const,
  ([isVirtual, startIndex, endIndex]) => {
    if (!isVirtual || endIndex <= startIndex) return;
    clearTimeout(needRangeTimer);
    needRangeTimer = setTimeout(() => emit('need-range', startIndex, endIndex), 120);
  },
  { immediate: true },
);

/**
 * Cell height (px) inside a pinned row — the row height minus the gap the prop
 * includes — or `null` when the rows are poster-derived. `null` (not 0) so every
 * consumer below spreads an EMPTY style object for the poster grid and its markup
 * stays byte-identical.
 */
const fixedCellHeight = computed(() =>
  fixedRows.value ? fixedRowContentHeight(forcedRowHeight.value ?? 0) : null,
);

/**
 * `grid-auto-rows` for a pinned-row renderer: the grid CONTAINER enforces the row
 * height that the windowing math assumes, instead of trusting each `#card`
 * renderer to pin itself (S68 review, finding 3). Every row here is implicit (no
 * `grid-template-rows`), so this applies to all of them. Renderers should still
 * clip their own content (`overflow: hidden`), but they can no longer desync
 * `padTop`/`totalHeight` from the layout by growing taller than their track.
 */
const fixedRowsStyle = computed(() =>
  fixedCellHeight.value === null ? {} : { gridAutoRows: `${fixedCellHeight.value}px` },
);

// A forced column count is a LAYOUT decision, so it applies even before the
// container is measured (jsdom / SSR / first paint) — otherwise a list view would
// flash as an auto-fit poster grid, and its rows would be laid out at a different
// column count than the windowing math assumes.
const gridStyle = computed(() => ({
  gridTemplateColumns:
    virtualized.value || forcedColumns.value !== null
      ? `repeat(${effectiveColumns.value}, minmax(0, 1fr))`
      : `repeat(auto-fill, minmax(${cardSize.value}px, 1fr))`,
  ...fixedRowsStyle.value,
}));

const sizerStyle = computed(() =>
  virtualized.value ? { height: `${windowResult.value.totalHeight}px` } : {},
);

const innerStyle = computed(() =>
  virtualized.value
    ? { position: 'absolute' as const, top: '0', left: '0', right: '0', transform: `translateY(${windowResult.value.padTop}px)` }
    : {},
);

const skeletonStyle = computed(() => ({
  gridTemplateColumns:
    forcedColumns.value !== null
      ? `repeat(${effectiveColumns.value}, minmax(0, 1fr))`
      : `repeat(auto-fill, minmax(${cardSize.value}px, 1fr))`,
  ...fixedRowsStyle.value,
}));

/**
 * Placeholder-cell sizing. With a pinned `rowHeight` the cell is given the exact
 * cell height (`fixedCellHeight`) so a not-yet-loaded index in the pre-sized grid
 * can never render taller than the row the windowing math reserved for it — a
 * full-width 2:3 poster skeleton in a one-column list view would otherwise be
 * ~1000px tall and shove every following row out of position. Belt to
 * `grid-auto-rows`' braces: this keeps working if the cell is ever taken out of
 * the grid's own row flow.
 */
const skeletonCellStyle = computed(() =>
  fixedCellHeight.value === null ? {} : { height: `${fixedCellHeight.value}px` },
);

// --- back to top ---
const showBackToTop = computed(() => virtualized.value && scrollTop.value > viewportHeight.value * 1.5);
function backToTop(): void {
  if (typeof window === 'undefined') return;
  const reduce =
    typeof window.matchMedia === 'function' &&
    window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  window.scrollTo?.({ top: 0, behavior: reduce ? 'auto' : 'smooth' });
}

/**
 * Scroll the window so the row containing `index` sits at the top — the A-Z
 * jump rail drives this with a letter's offset. Works for any index in the
 * pre-sized grid (on-demand paging fills the destination once it's in view).
 */
function scrollToIndex(index: number): void {
  if (typeof window === 'undefined') return;
  const cols = Math.max(1, effectiveColumns.value);
  const rowY = Math.floor(Math.max(0, index) / cols) * effectiveRowHeight.value;
  // Instant, not smooth: an A-Z jump can span thousands of rows — animating
  // through them is janky and would fetch every page flown past. Jump straight
  // to the target so a single settled-window `need-range` loads that letter.
  window.scrollTo?.({ top: Math.max(0, sizerTop + rowY), behavior: 'auto' });
}
defineExpose({ scrollToIndex });

// --- infinite scroll ---
let io: IntersectionObserver | null = null;
function attachSentinel(): void {
  if (io || typeof IntersectionObserver === 'undefined') return;
  io = new IntersectionObserver(
    (entries) => {
      if (entries.some((e) => e.isIntersecting) && props.hasMore && !props.loading && !props.loadingMore) {
        emit('load-more');
      }
    },
    { rootMargin: '400px 0px' },
  );
  if (sentinelEl.value) io.observe(sentinelEl.value);
}
function detachSentinel(): void {
  io?.disconnect();
  io = null;
}

// Re-observe when the sentinel mounts/unmounts (it only exists while hasMore).
watch(
  () => sentinelEl.value,
  (el) => {
    detachSentinel();
    if (el) {
      attachSentinel();
      scheduleMeasure();
    }
  },
);

// --- ResizeObserver on the sizer (re-attached when it mounts) ---
let ro: ResizeObserver | null = null;
function attachResizeObserver(): void {
  if (ro || typeof ResizeObserver === 'undefined' || !sizerEl.value) return;
  ro = new ResizeObserver(scheduleMeasure);
  ro.observe(sizerEl.value);
}
function detachResizeObserver(): void {
  ro?.disconnect();
  ro = null;
}

// The sizer only exists once items render (the skeleton/empty branches have
// none), so re-attach the RO + remeasure whenever it mounts — without this a
// container-width change that isn't a window resize would never re-window.
watch(
  () => sizerEl.value,
  (el) => {
    detachResizeObserver();
    if (el) {
      attachResizeObserver();
      scheduleMeasure();
    }
  },
);

onMounted(() => {
  measure();
  if (typeof window !== 'undefined') {
    // Throttle scroll measurements to avoid calling getBoundingClientRect on
    // every scroll event. The throttle uses a timestamp (not rAF) because
    // Firefox aggressively throttles rAF during scrolling, which caused the
    // window to visually "freeze". Resize stays rAF-coalesced (it can fire in
    // bursts and isn't latency-critical).
    window.addEventListener('scroll', throttledMeasure, { passive: true });
    window.addEventListener('resize', scheduleMeasure, { passive: true });
  }
  attachResizeObserver();
  attachSentinel();
});

onBeforeUnmount(() => {
  if (typeof window !== 'undefined') {
    window.removeEventListener('scroll', throttledMeasure);
    window.removeEventListener('resize', scheduleMeasure);
  }
  if (frame) {
    if (typeof cancelAnimationFrame === 'function') cancelAnimationFrame(frame);
    else clearTimeout(frame);
    frame = 0;
  }
  clearTimeout(needRangeTimer);
  detachResizeObserver();
  detachSentinel();
});

// Item-count changes (a new page appended) can shift total height — remeasure.
watch(
  () => props.items.length,
  () => nextTick(scheduleMeasure),
);
</script>

<template>
  <div class="media-grid-root">
    <!-- initial load -->
    <div
      v-if="loading && items.length === 0"
      class="media-grid media-grid--skeleton"
      :style="skeletonStyle"
      role="status"
      aria-busy="true"
      aria-label="Loading media"
    >
      <div
        v-for="n in skeletonCount"
        :key="n"
        class="skel-card"
        :style="skeletonCellStyle"
        aria-hidden="true"
      >
        <!-- Pinned-row renderers get one block at the exact row height; the poster
             grid keeps the poster/title/sub rhythm so there is no layout shift. -->
        <div v-if="fixedRows" class="skel-block" />
        <template v-else>
          <div class="skel-poster" />
          <div class="skel-title" />
          <div class="skel-sub" />
        </template>
      </div>
    </div>

    <!-- empty -->
    <div v-else-if="items.length === 0" class="media-grid-empty" role="status">
      <slot name="empty">
        <Icon name="film" class="media-grid-empty__icon" />
        <p class="media-grid-empty__title">No media found</p>
        <p class="media-grid-empty__hint">Try adjusting your filters.</p>
      </slot>
    </div>

    <!-- virtualized grid -->
    <template v-else>
      <div ref="sizerEl" class="media-grid-sizer" :style="sizerStyle">
        <div class="media-grid" :style="[gridStyle, innerStyle]">
          <template v-for="entry in visibleItems" :key="entry.item?.id ?? `skel-${entry.index}`">
            <slot v-if="entry.item" name="card" :item="entry.item" :index="entry.index">
              <MediaCard
                :item="entry.item"
                :can-match="canMatch"
                :lazy="false"
                @play="emit('play', entry.item)"
                @watchlist="emit('watchlist', entry.item)"
                @info="emit('info', entry.item)"
                @match="emit('match', entry.item)"
                @mark-watched="emit('mark-watched', entry.item)"
                @refresh="emit('refresh', entry.item)"
                @choose-poster="emit('choose-poster', entry.item)"
                @remove="emit('remove', entry.item)"
                @edit-metadata="emit('edit-metadata', entry.item)"
                @explore-data="emit('explore-data', entry.item)"
              />
            </slot>
            <!-- not-yet-loaded index in the pre-sized grid -->
            <div v-else class="skel-card" :style="skeletonCellStyle" aria-hidden="true">
              <div v-if="fixedRows" class="skel-block" />
              <template v-else>
                <div class="skel-poster" />
                <div class="skel-title" />
                <div class="skel-sub" />
              </template>
            </div>
          </template>
        </div>
      </div>

      <div
        v-if="loadingMore"
        class="media-grid-more"
        role="status"
        aria-live="polite"
      >
        <span class="media-grid-more__spinner" aria-hidden="true" />
        Loading more…
      </div>

      <div v-if="hasMore && !loadingMore" ref="sentinelEl" class="media-grid-sentinel" aria-hidden="true" />
    </template>

    <Transition name="media-grid-fade">
